    75→                    .let { devicesMap ->
    76→                        devicesMap.keys
    77→                            .filter { it.startsWith("com.apple.CoreSimulator.SimRuntime.iOS") }
    78→                            .map { devicesMap[it] as List<*> }
    79→                    }.map { jsonArray -> jsonArray.map { it as Map<String, *> } }
    80→                    .flatten()
    81→                    .filter { it["isAvailable"] as Boolean }
    82→                    .filter {
