   112→abstract class Injected {
   113→    @get:Inject abstract val execOperations: ExecOperations
   114→
   115→    @get:Inject abstract val projectLayout: ProjectLayout
   116→
   117→    fun runExec(commands: List<String>): String =
   118→        object : ByteArrayOutputStream() {
   119→            override fun write(
   120→                p0: ByteArray,
   121→                p1: Int,
   122→                p2: Int,
   123→            ) {
   124→                print(String(p0, p1, p2))
   125→                super.write(p0, p1, p2)
   126→            }
   127→        }.let { resultOutputStream ->
   128→            execOperations
   129→                .exec {
   130→                    if (System.getenv("JAVA_HOME") == null) {
   131→                        System.getProperty("java.home")?.let { javaHome ->
   132→                            environment =
   133→                                environment.toMutableMap().apply {
   134→                                    put("JAVA_HOME", javaHome)
   135→                                }
   136→                        }
   137→                    }
   138→                    commandLine = commands
   139→                    standardOutput = resultOutputStream
   140→                    println("commandLine: ${this.commandLine.joinToString(separator = " ")}")
   141→                }.apply { println("ExecResult: $this") }
   142→            String(resultOutputStream.toByteArray())
   143→        }
   144→}
